/// A standard pseudo-element without arguments, and `::picker(select)`.
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Hash)]
#[non_exhaustive]
pub enum PseudoElement {
    /// `::after`.
    After,
    /// `::backdrop`.
    Backdrop,
    /// `::before`.
    Before,
    /// `::checkmark`.
    Checkmark,
    /// `::cue`.
    Cue,
    /// `::details-content`.
    DetailsContent,
    /// `::file-selector-button`.
    FileSelectorButton,
    /// `::first-letter`.
    FirstLetter,
    /// `::first-line`.
    FirstLine,
    /// `::grammar-error`.
    GrammarError,
    /// `::marker`.
    Marker,
    /// `::picker(select)`.
    PickerSelect,
    /// `::picker-icon`.
    PickerIcon,
    /// `::placeholder`.
    Placeholder,
    /// `::selection`.
    Selection,
    /// `::spelling-error`.
    SpellingError,
    /// `::target-text`.
    TargetText,
    /// `::view-transition`.
    ViewTransition,
}

impl PseudoElement {
    /// The name without its colons.
    #[must_use]
    pub fn name(self) -> &'static str {
        match self {
            Self::After => "after",
            Self::Backdrop => "backdrop",
            Self::Before => "before",
            Self::Checkmark => "checkmark",
            Self::Cue => "cue",
            Self::DetailsContent => "details-content",
            Self::FileSelectorButton => "file-selector-button",
            Self::FirstLetter => "first-letter",
            Self::FirstLine => "first-line",
            Self::GrammarError => "grammar-error",
            Self::Marker => "marker",
            Self::PickerSelect => "picker(select)",
            Self::PickerIcon => "picker-icon",
            Self::Placeholder => "placeholder",
            Self::Selection => "selection",
            Self::SpellingError => "spelling-error",
            Self::TargetText => "target-text",
            Self::ViewTransition => "view-transition",
        }
    }
}

